public class Student {
    private String name;
    private double average;

    public Student(String name, double average) {
        this.name = name;
        if (average > 0.0) {
            if (average <= 100.0) {
                this.average = average;
            }
        }
    }

    public void setAverage(double average) {
        if (average > 0.0) {
            if (average <= 100.0) {
                this.average = average;
            }
        }
    }

    public String getLetterGrade() {
        if (average >= 90.0) return "A";
        else if (average >= 80.0) return "B";
        else if (average >= 70.0) return "C";
        else if (average >= 60.0) return "D";
        else return "F";
    }

    public static void main(String[] args) {
        Student s = new Student("Alex", 0.0);
        s.setAverage(85.0);
        s.setAverage(105.0);
        Student s2 = new Student("Sam", -10.0);
        System.out.printf("%.1f %s %.1f %s",
            s.average, s.getLetterGrade(), s2.average, s2.getLetterGrade());
    }
}

int passes = 0;
int failures = 0;
int studentCounter = 1;

while (studentCounter <= 5) {
    int result = (studentCounter % 2 != 0) ? 1 : 2;
    if (result == 1) {
        ++passes;
    } else {
        failures++;
    }
    studentCounter += 2;
}

String status = passes > 2 ? "Bonus" : "NoBonus";
System.out.printf("%d %d %d %s", passes, failures, studentCounter, status);

