int x = 24;
int y = 3;
int count = 0;

while (x > y) {
    int step;
    if (x % 3 == 0) {
        step = 2;
    } else {
        step = 3;
    }
    x -= y += step;
    count++;
}

System.out.printf("%d %d %d", x, y, count);
